<?php
require_once __DIR__.'/config/config.php';
$slug=trim($_GET['slug']??'');
$s=db()->prepare("SELECT s.*,c.name category FROM stories s LEFT JOIN categories c ON c.id=s.category_id WHERE s.slug=? AND s.status='PUBLISHED' LIMIT 1");$s->execute([$slug]);$story=$s->fetch();
if(!$story){http_response_code(404);exit('Story not found.');}
$paragraphs=preg_split("/\R{2,}/",trim($story['content']));
$gallery=[];$structuredSources=[];$correctionSent=false;
try{$g=db()->prepare('SELECT * FROM story_images WHERE story_id=? ORDER BY sort_order,id');$g->execute([$story['id']]);$gallery=$g->fetchAll();$src=db()->prepare('SELECT * FROM story_sources WHERE story_id=? ORDER BY id');$src->execute([$story['id']]);$structuredSources=$src->fetchAll();track_event('view',(int)$story['id']);}catch(Throwable $e){}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['correction_message'])){verify_csrf();$message=trim($_POST['correction_message']);if($message!==''){try{$r=db()->prepare('INSERT INTO correction_reports(story_id,name,email,message) VALUES(?,?,?,?)');$r->execute([(int)$story['id'],trim($_POST['correction_name']??''),trim($_POST['correction_email']??''),$message]);$correctionSent=true;}catch(Throwable $e){}}}
